import { MeshPhysicalNodeMaterial, MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec2, mix, color, smoothstep } from 'three/tsl';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

function disposeObject3D(obj) {
  obj.traverse((child) => {
    if (child.geometry) child.geometry.dispose();
    if (child.material) {
      const mats = Array.isArray(child.material) ? child.material : [child.material];
      mats.forEach((m) => {
        if (m.map) m.map.dispose();
        m.dispose();
      });
    }
  });
}

function makeSlabGeometry(THREE, w, h, depth) {
  const shape = new THREE.Shape();
  const hw = w / 2;
  const hh = h / 2;
  shape.moveTo(-hw, -hh);
  shape.lineTo(hw, -hh);
  shape.lineTo(hw, hh);
  shape.lineTo(-hw, hh);
  shape.lineTo(-hw, -hh);
  const geo = new THREE.ExtrudeGeometry(shape, {
    depth: depth,
    bevelEnabled: true,
    bevelThickness: 0.04,
    bevelSize: 0.04,
    bevelSegments: 2,
    curveSegments: 4,
  });
  geo.translate(0, 0, -depth / 2);
  return geo;
}

function makeCellGradientNode() {
  const t = uv().x.add(uv().y).mul(0.5);
  const base = mix(color('#101017'), color('#1a1a22'), t);
  const band = smoothstep(0.37, 0.4, t).sub(smoothstep(0.4, 0.43, t));
  return base.add(band.mul(0.06));
}

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const group = new THREE.Group();
  group.name = 'bento-metrics-grid';

  const colors = (config.intent && config.intent.visualSpec && config.intent.visualSpec.colors) || {};
  const accent = colors.accent || '#ff2a38';
  const surfaceColor = colors.surface || '#14141a';
  const paper = colors.paper || '#e8ecf2';
  const gradientStops = colors.gradientStops || [
    { at: 0, hex: '#101017' },
    { at: 1, hex: '#1a1a22' },
  ];

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const findByRoleText = (fs) => items.find((i) => i.typography && i.typography.fontSize === fs) || null;

  // pull text items by intended slot, fall back to positional order
  const captionItem = items.find((i) => i.role === 'caption') || items[0];
  const valueLargeItem = items.find((i) => i.role === 'valueLarge') || items[1];
  const dominantLabelItem = items[2];
  const value1Item = items[3];
  const label1Item = items[4];
  const value2Item = items[5];
  const label2Item = items[6];

  const cleanupFns = [];
  const tweens = [];

  // ---------- BACKDROP ----------
  const backdropGeo = new THREE.PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial();
  const stop0 = color(gradientStops[0].hex);
  const stop1 = color(gradientStops[gradientStops.length - 1].hex);
  backdropMat.colorNode = mix(stop0, stop1, uv().y);
  const backdrop = new THREE.Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  group.add(backdrop);

  // ---------- CONTACT SHADOW ----------
  const shadowGeo = new THREE.PlaneGeometry(6.5, 4.5);
  const shadowMat = new MeshBasicNodeMaterial();
  shadowMat.transparent = true;
  const d = uv().sub(vec2(0.5, 0.5)).length();
  shadowMat.colorNode = color('#000000');
  shadowMat.opacityNode = smoothstep(0.5, 0.05, d).mul(0.5);
  const shadowPlane = new THREE.Mesh(shadowGeo, shadowMat);
  shadowPlane.position.set(0, -0.1, -0.15);
  group.add(shadowPlane);

  // ---------- LOCAL LIGHTS ----------
  const rimLight = new THREE.DirectionalLight(new THREE.Color(accent), 0.6);
  rimLight.position.set(2.5, -1.5, 3.0);
  group.add(rimLight);

  const chamferLight = new THREE.DirectionalLight(0xffffff, 0.5);
  chamferLight.position.set(-2.0, 3.0, 4.0);
  group.add(chamferLight);

  // ---------- CELL DEFINITIONS ----------
  const cellDepth = 0.06;
  const cells = [];

  function buildCell({ w, h, x, y, isDominant, valueText, valueFontSize, labelText }) {
    const cellGroup = new THREE.Group();
    cellGroup.position.set(x, y, 0);

    const slabGeo = makeSlabGeometry(THREE, w, h, cellDepth);
    const slabMat = new MeshPhysicalNodeMaterial();
    slabMat.colorNode = makeCellGradientNode();
    slabMat.roughness = 0.5;
    slabMat.metalness = 0.45;
    slabMat.clearcoat = 0.2;
    slabMat.clearcoatRoughness = 0.3;
    const slab = new THREE.Mesh(slabGeo, slabMat);
    cellGroup.add(slab);

    // tick bar - top left inside padding
    const innerHalfW = w / 2 - 0.5;
    const innerHalfH = h / 2 - 0.5;
    const tickGeo = new THREE.BoxGeometry(0.4, 0.05, 0.02);
    const tickMat = new MeshStandardNodeMaterial();
    tickMat.color = new THREE.Color(accent);
    tickMat.emissive = new THREE.Color(accent);
    tickMat.emissiveIntensity = 1.3;
    tickMat.roughness = 0.4;
    tickMat.metalness = 0.2;
    const tick = new THREE.Mesh(tickGeo, tickMat);
    tick.position.set(-innerHalfW + 0.2, innerHalfH - 0.025, cellDepth / 2 + 0.02);
    cellGroup.add(tick);

    // value text
    const valueNode = ctx.fontAtlas.createText(valueText, {
      fontSize: valueFontSize,
      color: paper,
      align: 'left',
      letterSpacingPx: -valueFontSize * 0.005,
    });
    valueNode.position.set(-innerHalfW, isDominant ? 0.15 : innerHalfH - 0.55, cellDepth / 2 + 0.02);
    cellGroup.add(valueNode);

    // label text
    const labelNode = ctx.fontAtlas.createText(labelText, {
      fontSize: 18,
      color: '#aab0ba',
      align: 'left',
      letterSpacingPx: 18 * 0.08,
    });
    labelNode.position.set(
      -innerHalfW,
      isDominant ? -0.45 : innerHalfH - 0.55 - (valueFontSize / 124) * 0.62 - 0.15,
      cellDepth / 2 + 0.02
    );
    cellGroup.add(labelNode);

    group.add(cellGroup);
    cells.push(cellGroup);
    return { cellGroup, slabGeo, slabMat, tickGeo, tickMat, valueNode, labelNode };
  }

  const dominant = buildCell({
    w: 3.25,
    h: 3.5,
    x: -1.125,
    y: 0,
    isDominant: true,
    valueText: valueLargeItem ? valueLargeItem.text : '0.002 mm',
    valueFontSize: 124,
    labelText: dominantLabelItem ? dominantLabelItem.text : 'Case tolerance, CNC pass',
  });

  const secondaryTop = buildCell({
    w: 2.0,
    h: 1.625,
    x: 1.75,
    y: 0.9375,
    isDominant: false,
    valueText: value1Item ? value1Item.text : '38 h',
    valueFontSize: 68,
    labelText: label1Item ? label1Item.text : 'Power reserve, NA-01',
  });

  const secondaryBottom = buildCell({
    w: 2.0,
    h: 1.625,
    x: 1.75,
    y: -0.9375,
    isDominant: false,
    valueText: value2Item ? value2Item.text : '214',
    valueFontSize: 68,
    labelText: label2Item ? label2Item.text : 'Components per calibre',
  });

  // ---------- HEADER CAPTION ----------
  const headerText = ctx.fontAtlas.createText(captionItem ? captionItem.text : 'ATELIER METRICS / Q2 2026', {
    fontSize: 18,
    color: paper,
    align: 'left',
    letterSpacingPx: 18 * 0.12,
  });
  headerText.position.set(-2.75, 2.25, 0.02);
  group.add(headerText);

  // ---------- ENTRANCE ANIMATION (stagger-cards / fade-up, dominant first) ----------
  const orderedCells = [dominant.cellGroup, secondaryTop.cellGroup, secondaryBottom.cellGroup];
  orderedCells.forEach((c, i) => {
    const baseY = c.position.y;
    c.position.y = baseY + 0.2;
    const originalOpacityTargets = [];
    c.traverse((child) => {
      if (child.material) {
        const mats = Array.isArray(child.material) ? child.material : [child.material];
        mats.forEach((m) => {
          m.transparent = true;
          m.opacity = 0;
          originalOpacityTargets.push(m);
        });
      }
    });
    const tl = gsap.timeline({ delay: i * 0.08 });
    tl.to(c.position, { y: baseY, duration: 0.5, ease: 'power2.out' }, 0);
    originalOpacityTargets.forEach((m) => {
      tl.to(m, { opacity: 1, duration: 0.5, ease: 'power2.out' }, 0);
    });
    tweens.push(tl);
  });

  headerText.traverse((child) => {
    if (child.material) {
      const mats = Array.isArray(child.material) ? child.material : [child.material];
      mats.forEach((m) => {
        m.transparent = true;
        m.opacity = 0;
        const tw = gsap.to(m, { opacity: 1, duration: 0.5, ease: 'power2.out', delay: 0.1 });
        tweens.push(tw);
      });
    }
  });

  // ---------- HOVER INTERACTION ----------
  let activeTween = null;
  function onPointerEnter() {
    if (activeTween) activeTween.kill();
    activeTween = gsap.to(group.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out(2)' });
    tweens.push(activeTween);
  }
  function onPointerLeave() {
    if (activeTween) activeTween.kill();
    group.scale.set(1.04, 1.04, 1.04);
    activeTween = gsap.to(group.scale, { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' });
    tweens.push(activeTween);
  }

  group.userData.handlers = {
    onPointerEnter,
    onPointerOver: onPointerEnter,
    onPointerLeave,
    onPointerOut: onPointerLeave,
  };

  // ---------- CLEANUP ----------
  group.userData.cleanup = () => {
    tweens.forEach((t) => t.kill && t.kill());
    disposeObject3D(group);
    rimLight.dispose && rimLight.dispose();
    chamferLight.dispose && chamferLight.dispose();
  };

  return group;
}
